import { useParams, Link } from "react-router-dom";
import { useState, useEffect } from "react";
import Card from "../components/Card";

export default function RoadmapPage() {
  const { name } = useParams();

  const [domain, setDomain] = useState("");
  const [roadmapPlan, setRoadmapPlan] = useState([]);
  const [currentDay, setCurrentDay] = useState(1);
  const [completedTasks, setCompletedTasks] = useState({});

  const timeline = localStorage.getItem("timeline") || "3 months";

  useEffect(() => {
    setDomain(name?.toLowerCase());
  }, [name]);

  // 🔥 ALL DOMAINS (FULL)
  const topicMap = {
    "web-development": [
      "HTML","CSS","Flexbox","JavaScript","DOM","React","API","Node.js","MongoDB","Project"
    ],
    "ai-and-ml": [
      "Python","NumPy","Pandas","Visualization","Statistics","ML Basics","Regression","Deep Learning","Project"
    ],
    "data-science": [
      "Python","NumPy","Pandas","Data Cleaning","Visualization","EDA","Statistics","ML Basics","Projects"
    ],
    "cloud-and-devops": [
      "Linux","Networking","Git","Docker","CI/CD","AWS","Kubernetes","Monitoring","Deployment","Project"
    ],
    "cybersecurity": [
      "Networking","Cryptography","Linux Security","Web Security","OWASP","Ethical Hacking","Pen Testing","Tools","Project"
    ],
    "mobile-development": [
      "Java/Kotlin","Android Studio","UI Design","Layouts","API Integration","Database","Firebase","Testing","Deployment","Project"
    ],
    "blockchain": [
      "Blockchain Basics","Cryptography","Bitcoin","Ethereum","Smart Contracts","Solidity","DApps","Web3","Project"
    ],
    "ui-ux-design": [
      "Design Principles","Color Theory","Typography","Wireframing","Figma","Prototyping","User Research","UX Flow","Project"
    ],
    "big-data": [
      "Big Data Basics","Hadoop","MapReduce","Spark","Kafka","ETL","Pipelines","Analytics","Project"
    ],
    "networking": [
      "OSI Model","TCP/IP","IP Addressing","Routing","Switching","DNS","Firewalls","Security","Troubleshooting","Project"
    ]
  };

  const topics = topicMap[domain] || ["Basics"];

  // 🚀 GENERATE PLAN
  const generatePlan = () => {
    let totalDays = 90;

    if (timeline.includes("month")) totalDays = parseInt(timeline) * 30;
    else if (timeline.includes("year")) totalDays = parseInt(timeline) * 365;

    const plan = [];
    let index = 0;

    for (let day = 0; day < totalDays; day++) {
      const daily = [];
      const count = 3 + Math.floor(Math.random() * 3);

      for (let i = 0; i < count; i++) {
        daily.push(topics[index % topics.length]);
        index++;
      }

      plan.push(daily);
    }

    return plan;
  };

  // ✅ INIT
  useEffect(() => {
    if (domain) {
      const existingPlan = sessionStorage.getItem("roadmapPlan");

      if (!existingPlan) {
        const plan = generatePlan();
        sessionStorage.setItem("roadmapPlan", JSON.stringify(plan));
        sessionStorage.setItem("currentDay", "1");
        sessionStorage.setItem("completedTasks", "{}");
      }

      setRoadmapPlan(JSON.parse(sessionStorage.getItem("roadmapPlan")));
      setCurrentDay(parseInt(sessionStorage.getItem("currentDay") || "1"));
      setCompletedTasks(JSON.parse(sessionStorage.getItem("completedTasks") || "{}"));
    }
  }, [domain]);

  // 🔥 REAL-TIME SYNC
  useEffect(() => {
    const sync = () => {
      setCompletedTasks(JSON.parse(sessionStorage.getItem("completedTasks") || "{}"));
      setCurrentDay(parseInt(sessionStorage.getItem("currentDay") || "1"));
    };

    window.addEventListener("storage", sync);
    window.addEventListener("focus", sync);

    return () => {
      window.removeEventListener("storage", sync);
      window.removeEventListener("focus", sync);
    };
  }, []);

  // 🔥 CARRY FORWARD
  const getTasksForDay = (day) => {
    const prevIncomplete =
      (roadmapPlan[day - 2] || []).filter(
        task => !(completedTasks[day - 1] || []).includes(task)
      );

    const todayTasks = roadmapPlan[day - 1] || [];

    return [...prevIncomplete, ...todayTasks];
  };

  // 🔥 AUTO NEXT DAY
  useEffect(() => {
    const todayTasks = getTasksForDay(currentDay);
    const completedToday = completedTasks[currentDay] || [];

    if (
      todayTasks.length > 0 &&
      todayTasks.every(task => completedToday.includes(task))
    ) {
      const nextDay = currentDay + 1;
      sessionStorage.setItem("currentDay", nextDay.toString());
      setCurrentDay(nextDay);
    }
  }, [completedTasks]);

  // ✅ PROGRESS
  const totalTasks = roadmapPlan.flat().length;
  const completedCount = Object.values(completedTasks).flat().length;

  const progress = totalTasks
    ? (completedCount / totalTasks) * 100
    : 0;

  return (
    <div className="space-y-8 text-white">
      <Card title="Learning Roadmap">

        <h2 className="text-xl font-bold capitalize">
          🚀 {domain}
        </h2>

        {/* PROGRESS */}
        <div className="mt-4">
          <div className="w-full bg-slate-700 h-3 rounded-full">
            <div
              className="h-3 rounded-full"
              style={{
                width: `${progress}%`,
                background: "linear-gradient(90deg, #22c55e, #4f46e5)"
              }}
            />
          </div>
          <p className="text-gray-400 mt-2">
            {Math.floor(progress)}% completed
          </p>
        </div>

        {/* DAY */}
        <h3 className="mt-4">
          Day {currentDay} / {roadmapPlan.length || 1}
        </h3>

        {/* TASKS */}
        <div className="grid gap-3 mt-4">
          {getTasksForDay(currentDay).map((task, i) => (
            <div
              key={i}
              className="p-4 bg-slate-800 rounded-xl border border-slate-700"
            >
              📌 {task}
            </div>
          ))}
        </div>

        <Link to="/tasks">
          <button className="mt-6 px-6 py-3 bg-teal-500 rounded-xl">
            Go to Tasks →
          </button>
        </Link>

      </Card>
    </div>
  );
}
